import sys

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1

    adj = [[] for _ in range(N + 1)]
    for _ in range(N - 1):
        a = int(data[idx]); idx += 1
        b = int(data[idx]); idx += 1
        adj[a].append(b)
        adj[b].append(a)

    in_G = [False] * (N + 1)
    has_high = False
    for v in range(1, N + 1):
        if len(adj[v]) >= 4:
            in_G[v] = True
            has_high = True

    if not has_high:
        print(-1)
        return

    G_adj = [[] for _ in range(N + 1)]
    for v in range(1, N + 1):
        if in_G[v]:
            for u in adj[v]:
                if in_G[u]:
                    G_adj[v].append(u)

    visited = [False] * (N + 1)
    f = [0] * (N + 1)
    parent = [0] * (N + 1)
    best_k = 0

    for start in range(1, N + 1):
        if not in_G[start] or visited[start]:
            continue
        order = []
        parent[start] = -1
        visited[start] = True
        stack = [start]
        while stack:
            v = stack.pop()
            order.append(v)
            for u in G_adj[v]:
                if not visited[u]:
                    visited[u] = True
                    parent[u] = v
                    stack.append(u)

        for v in reversed(order):
            child_fs = []
            pv = parent[v]
            for u in G_adj[v]:
                if u != pv:
                    child_fs.append(f[u])
            child_fs.sort(reverse=True)
            s3 = sum(child_fs[:3])
            f[v] = 1 + s3
            if len(child_fs) >= 4:
                cand = 1 + s3 + child_fs[3]
            else:
                cand = 1 + s3
            if cand > best_k:
                best_k = cand

    if best_k == 0:
        print(-1)
    else:
        print(3 * best_k + 2)

main()

